import React, { useState, useEffect } from 'react';
import { ArrowDown, ArrowUp, Info, RefreshCw, Activity, CheckCircle2, Clock } from 'lucide-react';

const Sparkline = ({ data, color, height = 60 }: { data: number[], color: string, height?: number }) => {
    const max = Math.max(...data);
    const min = Math.min(...data);
    const range = max - min || 1;
    const width = 100;
    const step = width / (data.length > 1 ? data.length - 1 : 1);

    const points = data.map((val, i) => {
        const x = i * step;
        const y = height - ((val - min) / range) * height;
        return `${x},${y}`;
    }).join(' ');

    return (
        <svg width="100%" height={height} viewBox={`0 0 100 ${height}`} preserveAspectRatio="none" className="overflow-visible">
            <path
                d={`M0,${height} L${points} L100,${height} Z`}
                fill={color}
                fillOpacity="0.1"
                stroke="none"
            />
            <path
                d={`M${points}`}
                fill="none"
                stroke={color}
                strokeWidth="2"
                vectorEffect="non-scaling-stroke"
            />
        </svg>
    );
};

const MetricCard = ({ title, value, unit, subValue, subLabel, data, color, icon: Icon }: any) => (
    <div className="bg-white p-6 rounded-sm border border-slate-200 shadow-sm">
        <div className="flex justify-between items-start mb-2">
            <div className="flex items-center gap-2">
                <h3 className="text-sm font-bold text-slate-700">{title}</h3>
                <Info size={14} className="text-slate-400 cursor-help" />
            </div>
            {Icon && <Icon size={16} className="text-slate-400" />}
        </div>

        <div className="flex justify-between items-end mb-4">
            <div>
                <div className="text-xs text-slate-500 font-semibold uppercase tracking-wider mb-1">CURRENT</div>
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-slate-900">{value}</span>
                    <span className="text-sm text-slate-500 font-medium">{unit}</span>
                </div>
            </div>
            <div className="text-right">
                <div className="text-xs text-slate-500 font-semibold uppercase tracking-wider mb-1">{subLabel}</div>
                <div className="flex items-baseline gap-1 justify-end">
                    <span className="text-xl font-bold text-slate-700">{subValue}</span>
                </div>
            </div>
        </div>

        <div className="h-16 w-full mt-4">
            <Sparkline data={data} color={color} />
        </div>

        <div className="mt-4 pt-4 border-t border-slate-100">
            <div className="text-xs text-slate-500 font-semibold uppercase tracking-wider mb-1">HISTORY (LAST 10 MINS)</div>
        </div>
    </div>
);

const SystemStatusContent = () => {
    const [status, setStatus] = useState<any>(null);
    const [loading, setLoading] = useState(true);

    // Real Data Accumulators
    const [latencyHistory, setLatencyHistory] = useState<number[]>(Array(20).fill(0));
    const [successRateHistory, setSuccessRateHistory] = useState<number[]>(Array(20).fill(100));

    const checkStatus = async () => {
        setLoading(true);
        try {
            const res = await fetch('/api/system-status');
            const data = await res.json();
            setStatus(data);

            // Update Latency History
            const latency = data.checks?.database?.latency ? parseInt(data.checks.database.latency) : 0;
            setLatencyHistory(prev => [...prev.slice(1), latency]);

            // Update Success Rate History
            const rate = data.checks?.metrics?.success_rate ? parseFloat(data.checks.metrics.success_rate) : 0;
            setSuccessRateHistory(prev => [...prev.slice(1), rate]);

        } catch (err: any) {
            console.error("System Status Check Failed:", err);
            setStatus({
                status: 'down',
                message: err.message || 'Failed to fetch system status',
                location: 'Frontend Client (SystemStatusContent.tsx)',
                stack: err.stack || String(err),
                timestamp: new Date().toISOString()
            });
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        checkStatus();
        const interval = setInterval(checkStatus, 30000);
        return () => clearInterval(interval);
    }, []);

    // Helper to calculate time ago
    const getTimeAgo = (dateString: string) => {
        if (!dateString || dateString === 'Never') return 'Never';
        const diff = Math.floor((Date.now() - new Date(dateString).getTime()) / 60000);
        if (diff < 1) return 'Just now';
        return `${diff} min ago`;
    };

    const dbLatency = status?.checks?.database?.latency ? parseInt(status.checks.database.latency) : 0;
    const successRate = status?.checks?.metrics?.success_rate || '0.0';
    const lastTxnTime = getTimeAgo(status?.checks?.payments?.last_transaction);
    const lastWebhookTime = getTimeAgo(status?.checks?.payments?.last_webhook);

    const [lastUpdated, setLastUpdated] = useState<string>('');

    useEffect(() => {
        setLastUpdated(new Date().toLocaleTimeString());
    }, [status]); // Update timestamp whenever status updates

    return (
        <div className="min-h-screen bg-slate-50/50 font-sans text-slate-900">
            {/* Simple Header */}
            <div className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-10">
                <div className="flex items-center gap-2">
                    <Activity size={24} className="text-blue-600" />
                    <h1 className="text-xl font-bold text-slate-800">System Status</h1>
                </div>
                <div className="flex items-center gap-3">
                    <span className="text-xs text-slate-500 font-medium">
                        Last updated: {lastUpdated}
                    </span>
                    <button onClick={checkStatus} className="p-2 text-slate-400 hover:text-blue-600 transition-colors bg-slate-50 rounded-lg border border-slate-200 hover:border-blue-200">
                        <RefreshCw size={18} className={loading ? 'animate-spin' : ''} />
                    </button>
                </div>
            </div>

            {/* Active Incidents / Logs */}
            {status?.status === 'down' && (
                <div className="px-6 pt-6 max-w-7xl mx-auto animate-fade-in">
                    <div className="bg-rose-50 border border-rose-200 rounded-lg p-4 flex items-start gap-4 shadow-sm">
                        <div className="p-2 bg-rose-100 rounded-full shrink-0">
                            <Activity size={20} className="text-rose-600" />
                        </div>
                        <div className="flex-1 min-w-0">
                            <h3 className="text-rose-900 font-bold text-sm uppercase tracking-wide mb-1">Critical System Alert</h3>
                            <p className="text-rose-800 font-bold mb-2">{status.message || 'Unknown System Error'}</p>

                            {status.location && (
                                <div className="flex items-center gap-2 text-xs text-rose-700 mb-2">
                                    <span className="font-bold">Location:</span>
                                    <span className="font-mono bg-rose-100 px-1.5 py-0.5 rounded">{status.location}</span>
                                </div>
                            )}

                            {status.stack && (
                                <div className="mt-3 bg-rose-950/5 rounded-lg p-3 overflow-x-auto">
                                    <p className="text-[10px] font-bold text-rose-900 uppercase mb-1">Stack Trace</p>
                                    <pre className="text-[10px] text-rose-800 font-mono whitespace-pre-wrap break-all">
                                        {status.stack}
                                    </pre>
                                </div>
                            )}

                            <div className="mt-2 text-xs text-rose-600 font-mono">
                                Timestamp: {status.timestamp ? new Date(status.timestamp).toLocaleString() : new Date().toLocaleString()}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Content */}
            <div className="p-6 space-y-6 max-w-7xl mx-auto">
                <h2 className="text-lg font-semibold text-slate-700">Real-time Metrics</h2>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* 1. Database Response Time (Real) */}
                    <MetricCard
                        title="Database Latency"
                        value={dbLatency}
                        unit="ms"
                        subLabel="STATUS"
                        subValue={status?.checks?.database?.status === 'connected' ? 'Connected' : 'Issue'}
                        data={latencyHistory}
                        color="#d946ef" // Fuchsia-500
                        icon={Activity}
                    />

                    {/* 2. Success Rate (Real) */}
                    <MetricCard
                        title="Success Rate"
                        value={successRate}
                        unit="%"
                        subLabel="LAST 50 TXNS"
                        subValue={successRate + '%'}
                        data={successRateHistory}
                        color="#10b981" // Emerald-500
                        icon={CheckCircle2}
                    />

                    {/* 3. Payment Pulse (Real) */}
                    <div className="bg-white p-6 rounded-sm border border-slate-200 shadow-sm flex flex-col justify-between">
                        <div className="flex justify-between items-start mb-2">
                            <div className="flex items-center gap-2">
                                <h3 className="text-sm font-bold text-slate-700">Payment Pulse</h3>
                                <Info size={14} className="text-slate-400 cursor-help" />
                            </div>
                            <Clock size={16} className="text-slate-400" />
                        </div>

                        <div className="space-y-6 mt-2">
                            <div>
                                <div className="text-xs text-slate-500 font-semibold uppercase tracking-wider mb-1">LAST TRANSACTION</div>
                                <div className="flex items-baseline gap-1">
                                    <span className="text-3xl font-bold text-slate-900">{lastTxnTime}</span>
                                </div>
                                <div className="text-xs text-slate-400 mt-1">
                                    {status?.checks?.payments?.last_transaction ? new Date(status.checks.payments.last_transaction).toLocaleString() : '-'}
                                </div>
                            </div>

                            <div className="pt-4 border-t border-slate-100">
                                <div className="text-xs text-slate-500 font-semibold uppercase tracking-wider mb-1">LAST WEBHOOK</div>
                                <div className="flex items-baseline gap-1">
                                    <span className="text-2xl font-bold text-slate-700">{lastWebhookTime}</span>
                                </div>
                                <div className="text-xs text-slate-400 mt-1">
                                    {status?.checks?.payments?.last_webhook ? new Date(status.checks.payments.last_webhook).toLocaleString() : '-'}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SystemStatusContent;
